__version__ = "0.1.0" 

def hasMatch(s: str, p: str) -> bool: 
    star_index = p.index('*') 
    prefix = p[:star_index] 
    suffix = p[star_index + 1:] 

    # We need to check every possible position where the prefix can match in s 
    for i in range(len(s) - len(prefix) + 1): 
        if s.startswith(prefix, i): 
            # After matching the prefix, check if the suffix can match 
            if s[i + len(prefix):].startswith(suffix): 
                return True 
    return False

