from collections import Counter

def maxDifference(s: str) -> int:
    frequencies = Counter(s)
    max_odd = float('-inf')
    max_even = float('-inf')

    for count in frequencies.values():
        if count % 2 == 0:
            max_even = max(max_even, count)
        else:
            max_odd = max(max_odd, count)

    return max_odd - max_even

