def totalNumbers(digits: List[int]) -> int:
    from itertools import permutations
    distinct_numbers = set()
    for perm in permutations(digits, 3):
        if perm[0] != 0 and perm[2] % 2 == 0:
            distinct_numbers.add(perm)
    return len(distinct_numbers)

def maxContainers(n: int, w: int, maxWeight: int) -> int:
    total_cells = n * n
    total_weight_if_full = total_cells * w
    if total_weight_if_full <= maxWeight:
        return total_cells
    return maxWeight // w

