def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    dp = [1] * n  # dp[i] will hold the length of the longest subsequence ending at index i
    diffs = [0] * n  # to hold the differences for the subsequence

    for i in range(n):
        for j in range(i):
            diff = abs(nums[i] - nums[j])
            if dp[j] + 1 > dp[i] and (i == 0 or diffs[j] >= diff):
                dp[i] = dp[j] + 1
                diffs[i] = diff

    return max(dp)

