def maximumAmount(coins: List[List[int]]) -> int:
    if not coins or not coins[0]:
        return 0

    m, n = len(coins), len(coins[0])
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = max(coins[0][0], 0)

    for i in range(m):
        for j in range(n):
            for k in range(3):
                if i > 0:
                    previous_cell_value = dp[i - 1][j][k]
                    if coins[i][j] >= 0:
                        dp[i][j][k] = max(dp[i][j][k], previous_cell_value + coins[i][j])
                    else:
                        dp[i][j][k] = max(dp[i][j][k], previous_cell_value + coins[i][j])  # robbery
                        if k > 0:
                            dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k - 1] + coins[i][j])
                if j > 0:
                    previous_cell_value = dp[i][j - 1][k]
                    if coins[i][j] >= 0:
                        dp[i][j][k] = max(dp[i][j][k], previous_cell_value + coins[i][j])
                    else:
                        dp[i][j][k] = max(dp[i][j][k], previous_cell_value + coins[i][j])  # robbery
                        if k > 0:
                            dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k - 1] + coins[i][j])

    return max(dp[m - 1][n - 1])

