def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    future_events = []

    # Sort events by timestamp for processing
    events_sorted = sorted((int(event[1]), event) for event in events)

    for timestamp, event in events_sorted:
        # Process all future events that are due before this timestamp
        while future_events and future_events[0][0] <= timestamp:
            _, online_event = future_events.pop(0)
            user_id = int(online_event[2])
            online_status[user_id] = True

        if event[0] == "OFFLINE":
            user_id = int(event[2])
            online_status[user_id] = False
            # Schedule user to come back online after 60 time units
            return_time = timestamp + 60
            future_events.append((return_time, ["ONLINE", return_time, str(user_id)]))
        elif event[0] == "MESSAGE":
            mentions_string = event[2]
            mentioned_users = set()

            if mentions_string == "ALL":
                mentioned_users = set(range(numberOfUsers))
            elif mentions_string == "HERE":
                mentioned_users = {i for i in range(numberOfUsers) if online_status[i]}
            else:
                for mention in mentions_string.split():
                    if mention.startswith("id"):
                        user_id = int(mention[2:])
                        mentioned_users.add(user_id)

            for user_id in mentioned_users:
                mentions[user_id] += 1

    return mentions

