def maxFreeTime(eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
    n = len(startTime)
    meetings = list(zip(startTime, endTime))
    free_times = []
    prev_end = 0

    # Collect free time segments between meetings
    for start, end in meetings:
        if start > prev_end:
            free_times.append(start - prev_end)
        prev_end = end

    # Check for free time after the last meeting
    if prev_end < eventTime:
        free_times.append(eventTime - prev_end)

    max_free = 0

    # Using k reschedules to maximize free time
    for i in range(len(free_times)):
        if i + 1 < len(free_times):
            # Combine current free time with a next one by rescheduling a meeting
            merge_free_time = free_times[i] + free_times[i + 1]
            if k > 0:
                max_free = max(max_free, merge_free_time)
            k -= 1
        else:
            max_free = max(max_free, free_times[i])

    return max_free
